tool_calls.arguments:
{"command":"for p in app-d4bcf6f4b-5nwb9 app-d4bcf6f4b-fdx7c; do
  echo "=== $p ==="
  kubectl exec -n default $p -- bash -c 'nslookup peer.default.svc.cluster.local 2>&1 || true; nslookup peer.prod 2>&1 || true'
  echo "--- connection to service clusterIP ---"
  kubectl exec -n default $p -- wget -q -O /dev/null -T 3 http://10.96.210.62/ && echo HTTP_OK_FROM_SERVICE_IP"  || echo HTTP_FAIL_FROM_SERVICE_IP;
done"}

{"command":"for p in $(kubectl get pods -n default --field-selector status.phase=Running --label app=app -o jsonpath='{.items[*].metadata.name}'); do
  kubectl exec -n default $p -- sh -c '
    printf "%s -> " "$PEER_HOST"; wget -q -O - -T 3 "http://$PEER_HOST/" | grep -q "Welcome to nginx!" && echo HTTP_OK_WITH_BODY || (wget -S -O /dev/null -T 3 http://$PEER_HOST/ 2>&1 | tail -2; echo FAILED);
    if grep -q ok /shared/status; then printf " status=ok\n"; else printf " status=fail\n"; fi;
    sleep 5;'
done
echo ---; kubectl get deploy app -n default -o jsonpath='{.status.conditions.*}{"\n"}'"}

